import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, readableError } from '../api/client';

/**
 * What this site's own readers are reviewing.
 *
 * The catalogues above it come from TMDb and look the same for everybody.
 * This row is the only thing on the page that is generated by the people
 * using it, so an empty state here is honest rather than hidden: a new
 * install genuinely has no activity, and pretending otherwise with filler
 * would be the one dishonest panel in the app.
 */
export default function Trending() {
  const [state, setState] = useState({ items: [], loading: true, error: '' });

  useEffect(() => {
    let current = true;
    api
      .get('/reviews/feed/trending', { params: { limit: 12 } })
      .then(({ data }) => current && setState({ items: data.items, loading: false, error: '' }))
      .catch((err) =>
        current && setState({ items: [], loading: false, error: readableError(err, '') })
      );
    return () => {
      current = false;
    };
  }, []);

  // A row nobody has contributed to yet is left out entirely rather than
  // shown empty under a heading that promises activity.
  if (state.loading || state.error || !state.items.length) return null;

  return (
    <section className="trending">
      <header className="catalogue__header">
        <div>
          <h2 className="catalogue__title">Being reviewed here</h2>
          <p className="catalogue__subtitle">
            Ranked by how many people reviewed it, not by score.
          </p>
        </div>
      </header>

      <ul className="trending__list">
        {state.items.map((film) => (
          <li key={film.movieId}>
            <Link to={`/film/${film.movieId}`} className="trending__item">
              {film.poster ? (
                <img src={film.poster} alt="" loading="lazy" />
              ) : (
                <span className="trending__blank" aria-hidden="true">🎬</span>
              )}
              <span className="trending__title">{film.title || film.movieId}</span>
              <span className="trending__meta">
                <b>{film.average?.toFixed(1)}</b>
                <i>{film.reviews} review{film.reviews === 1 ? '' : 's'}</i>
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}
